package api.robot_task_p; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.List; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class RobotTaskControllerTest { @Mock RobotTaskService service; @InjectMocks RobotTaskController controller; @Test @DisplayName("UT-BE-ROBOT-TASK-CTRL-001 로봇 작업 목록을 조회한다") void list(){ List<RobotTaskDTO>x=List.of(); when(service.list()).thenReturn(x); assertThat(controller.list()).isSameAs(x); } @Test @DisplayName("UT-BE-ROBOT-TASK-CTRL-002 로봇 작업 상세를 조회한다") void detail(){ RobotTaskDTO x=new RobotTaskDTO(); when(service.detail(1)).thenReturn(x); assertThat(controller.detail(1)).isSameAs(x); } @Test @DisplayName("UT-BE-ROBOT-TASK-CTRL-003 출차 작업을 생성한다") void out(){ RobotTaskDTO x=new RobotTaskDTO(); when(service.createParkOutTask(1,2)).thenReturn(x); assertThat(controller.createParkOutTask(1,2)).isSameAs(x); } @Test @DisplayName("UT-BE-ROBOT-TASK-CTRL-004 재주차 작업을 생성한다") void repark(){ RobotTaskDTO x=new RobotTaskDTO(); when(service.createReparkTask(1)).thenReturn(x); assertThat(controller.createReparkTask(1)).isSameAs(x); } }
